# management, cryosurgery for BCC, HPE of BCC, nevoid BCC syndrome, SCC types, Bowen's, keratoacanthoma, Mohs surgery,
# cutaneous markers of internal malignancy); facts checked with IADVL 5e and NCCN/EADO concepts.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
